param([string]$Exe="$PSScriptRoot/../FileTransferApp/x64/Debug/FileTransferAppGui.exe")
$ErrorActionPreference='Stop';. "$PSScriptRoot/n_to_1.ps1" -Exe $Exe -HelpersOnly
Add-Type -AssemblyName System.Security
function Seed($name,$folder,$key){$dir=Folder $name;[IO.File]::WriteAllText((Join-Path $dir 'gui-settings.txt'),$folder,[Text.UTF8Encoding]::new($false));$plain=[Text.Encoding]::UTF8.GetBytes("FTA-TRUST-1`n127.0.0.1|$key`n");$sealed=[Security.Cryptography.ProtectedData]::Protect($plain,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser);[IO.File]::WriteAllBytes((Join-Path $dir 'gui-settings.txt.trusted'),$sealed)}
function Direct($a,$s){$a.G.Set(101,'127.0.0.1');$a.G.Set(102,[string]$s.Port);$a.G.Click(137);$a.G.Wait(107,'Connected:');Count $s 1;Assert (!$s.G.Text(138).Contains('unverified')) 'Legacy migration required unexpected manual approval'}
function Wait-NewError($g,$before){$w=[Diagnostics.Stopwatch]::StartNew();while($w.ElapsedMilliseconds -lt 5000){if([regex]::Matches($g.Text(108),'Display name must').Count -gt $before){return};Start-Sleep -Milliseconds 20};throw 'Name validation error missing'}
function Forget($observer,$target,$server){
 $role=if($server){'S'}else{'C'};$packet="FTA-DISC|2|R|$($target.Instance)|$($target.Port)|revoke-fixture|$role|$($target.ID)";$u=[Net.Sockets.UdpClient]::new()
 try{$u.Client.SetSocketOption([Net.Sockets.SocketOptionLevel]::IP,[Net.Sockets.SocketOptionName]::MulticastInterface,[Net.IPAddress]::Loopback.GetAddressBytes());$bytes=[Text.Encoding]::UTF8.GetBytes($packet);[void]$u.Send($bytes,$bytes.Length,'239.255.90.8',9001)}finally{$u.Dispose()}
 $w=[Diagnostics.Stopwatch]::StartNew();$selected=$false;while($w.ElapsedMilliseconds -lt 5000 -and !$selected){$rows=$observer.G.Devices();for($i=0;$i -lt $rows.Length;$i++){if($rows[$i].Contains('['+$target.Instance.Substring(0,8)+']')){$observer.G.SelectDevice($i);$selected=$true;break}};if(!$selected){Start-Sleep -Milliseconds 20}};Assert $selected 'Revocation fixture missing';$observer.G.Click(146);$observer.G.Wait(108,('Registered N:1 peer removed: '+$target.ID))
}
$s=$null;$a=$null;$bad=$null
try{
 $serverFolder=Folder 'old-server-download';$clientFolder=Folder 'old-client-download';$key='d'*64;Seed 'server' $serverFolder $key;Seed 'client' $clientFolder $key
 $oldServerHash=(Get-FileHash (Join-Path $run 'server/gui-settings.txt.trusted')).Hash;$oldClientHash=(Get-FileHash (Join-Path $run 'client/gui-settings.txt.trusted')).Hash
 $s=App 'server' $true 'server';$a=App 'client' $false 'client';Direct $a $s;Pass 'existing IP/shared-key registration migrates after valid mutual proof'
 Assert ((Get-FileHash (Join-Path $run 'server/gui-settings.txt.trusted')).Hash -eq $oldServerHash) 'Old server trust modified';Assert ((Get-FileHash (Join-Path $run 'client/gui-settings.txt.trusted')).Hash -eq $oldClientHash) 'Old client trust modified';Pass 'legacy trusted files and original keys remain unchanged'
 $expected=Join-Path $serverFolder ('peers/'+$a.ID);Select-Peer $s $a;$s.G.Wait(154,$expected);Pass 'legacy default download folder becomes safe per-PeerId server subfolders'
 $source=Join-Path $run 'client-download.bin';[IO.File]::WriteAllBytes($source,[byte[]](1..255));$s.G.Pick($source);$s.G.Click(113);$s.G.Wait(122,'Completed:');Hash $source (Join-Path $clientFolder 'client-download.bin');Assert (!(Test-Path (Join-Path $clientFolder 'peers'))) 'Server path policy applied to client';Pass 'client preserves its original single download folder for server-sent files'
 $a.G.Close();$a.G.Dispose();$s.G.Close();$s.G.Dispose();$oldA=$a.ID;$oldS=$s.ID;$a=App 'client';$s=App 'server';Assert ($a.ID -eq $oldA -and $s.ID -eq $oldS) 'Persistent identities changed';Direct $a $s;Pass 'migrated registrations, roles and identities survive both process restarts'
 Select-Peer $a $s;$a.G.Click(105);Count $s 0;$a.G.Wait(107,'Disconnected');$before=[regex]::Matches($a.G.Text(108),'Display name must').Count;$a.G.Set(150,'bad|name');$a.G.Click(151);Wait-NewError $a.G $before;Pass 'display-name separator injection is rejected'
 $before=[regex]::Matches($a.G.Text(108),'Display name must').Count;$a.G.Set(150,([string][char]0xac00)*33);$a.G.Click(151);Wait-NewError $a.G $before;Pass 'display name limit is measured in UTF-8 bytes'
 $unicode=([string][char]0xac00)+([char]0xb098)+([char]0xb2e4)+'-PC';$a.G.Set(150,$unicode);$a.G.Click(151);Start-Sleep -Milliseconds 300;$a.G.Close();$a.G.Dispose();$a=App 'client';Assert ($a.G.Text(150) -eq $unicode) 'Unicode name not restored';Direct $a $s;Select-Peer $s $a;Assert ($s.G.Text(153).Contains($unicode)) 'Handshake name not updated';Pass 'Unicode display-name edits persist and appear in subsequent authenticated handshakes'
 Forget $s $a $false;Forget $a $s $true;Select-Peer $a $s;$a.G.Click(105);Count $s 0;Count $a 0;$a.G.Close();$a.G.Dispose();$s.G.Close();$s.G.Dispose();$a=App 'client';$s=App 'server';$a.G.Set(101,'127.0.0.1');$a.G.Set(102,[string]$s.Port);$a.G.Click(137);$s.G.Wait(138,'unverified');$s.G.Click(139);$a.G.Wait(107,'Connected:');Assert ((Get-FileHash (Join-Path $run 'server/gui-settings.txt.trusted')).Hash -eq $oldServerHash) 'Legacy key was deleted during revocation';Pass 'revoked migrated keys stay revoked after restart without deleting legacy key files'
 $a.G.Close();$a.G.Dispose();$identity=Join-Path $run 'client/gui-settings.txt.peer-id';[IO.File]::WriteAllText($identity,'broken');$bad=[GuiDriver]::new($Exe,(Join-Path $run 'client'),$true,$false,$true);$bad.Wait(108,'Invalid persistent PeerId');Assert ([IO.File]::ReadAllText($identity) -eq 'broken') 'Invalid identity silently replaced';Pass 'invalid persistent identity is reported and never regenerated over recovery state'
}finally{if($bad){try{$bad.Dispose()}catch{}};foreach($x in @($a,$s)){if($x){try{[IO.File]::WriteAllText((Join-Path $x.Dir 'ui.log'),$x.G.Text(108))}catch{};try{$x.G.Dispose()}catch{}}};"N1 settings artifacts: $run"}
